import re


def validate_email(address):
    if not address or "@" not in address:
        return False
    local, _, domain = address.partition("@")
    if not local or not domain or "." not in domain:
        return False
    return bool(re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", address))


